            while end < w and grid[r][end] == color:
                end += 1
            if color != bg and end - c >= 2:
                bars.append((r, c, end - 1))
            c = end

    bar_cells = {
        (r, c)
        for r, lo, hi in bars
        for c in range(lo, hi + 1)
    }
    markers = [
        (r, c, grid[r][c])
        for r in range(h) for c in range(w)
        if grid[r][c] != bg and (r, c) not in bar_cells
    ]

    for r, c, color in markers:
        out[r][c] = 4

    for r, lo, hi in bars:
        direction = 1 if r == 0 else -1
        for c in (lo, hi):
            rr = r + direction
            while 0 <= rr < h:
                if grid[rr][c] == bg:
                    out[rr][c] = markers[0][2] if markers else bg
                else:
                    if (rr, c) not in bar_cells:
                        out[rr][c] = 4
                    break
                rr += direction

    return out
